import { useEffect, useState } from 'react';
import { getQuestionSuggestions } from '../../api/modelingQuestions';

/** Questions per batch: keeps one verification turn within the modeling query cap (spec090). */
export const MAX_QUESTIONS = 5;

/** A question as submitted to the assistant, keyed by the id the page generated for it. */
export type SubmittedQuestion = { id: string; question: string };

/** Short, unique ids generated by the page so the agent never invents or reuses question ids. */
export function questionIds(count: number, now = Date.now()): string[] {
  const stamp = now.toString(36);
  return Array.from({ length: count }, (_, i) => `q-${stamp}-${i + 1}`);
}

export function questionRequest(questions: string[], ids = questionIds(questions.length)): string {
  return '请为以下业务问题逐题生成验证用 SQL，不要保存问答对。每题：读取当前草稿模型、关系与业务规则确定口径；写一条只读 SQL（多表必须 JOIN … ON，Top N 可用 LIMIT），'
    + '用 wren_cli query 实际执行一次确认可运行（遵守时间门禁与单轮查询上限，语法错误最多修正一次）；'
    + '然后用 write_file 写入 knowledge/questions/<ID>.yml，字段为 question（原问题，不改写）、definition（指标、粒度、时间范围、过滤及你所作的假设）、sql。'
    + '问题缺少日期时，选择符合时间配置的近期有限范围并在 definition 中写明。不要调用 memory store，不要写 knowledge/sql/。'
    + '全部处理完后简要说明每题的口径；平台会试运行，用户在试问面板判断对错，确认正确的问答发布后才会在问数中被召回。\n'
    + questions.map((q, i) => `${i + 1}. [ID: ${ids[i]}] ${q}`).join('\n');
}

/**
 * spec091: when {@code groupId} is given the form is prefilled with platform-suggested questions
 * as real, editable text; the user may submit them as is, edit, delete or add rows.
 */
export default function QuestionIntakeForm({ onSubmit, onCancel, initial = false, groupId }: {
  onSubmit: (message: string, questions: SubmittedQuestion[]) => void;
  onCancel?: () => void;
  initial?: boolean;
  groupId?: string;
}) {
  const [rows, setRows] = useState(['', '', '']);
  const [suggesting, setSuggesting] = useState(!!groupId);
  const [suggested, setSuggested] = useState(false);
  const [paste, setPaste] = useState('');
  const [pasteError, setPasteError] = useState<string | null>(null);
  useEffect(() => {
    if (!groupId) return;
    let cancelled = false;
    setSuggesting(true);
    getQuestionSuggestions(groupId)
      .then(list => {
        if (cancelled || !list.length) return;
        // Never overwrite what the user started typing while suggestions were loading.
        setRows(previous => previous.some(x => x.trim()) ? previous : list.slice(0, MAX_QUESTIONS));
        setSuggested(true);
      })
      .catch(() => undefined)
      .finally(() => { if (!cancelled) setSuggesting(false); });
    return () => { cancelled = true; };
  }, [groupId]);
  const questions = [...new Set(rows.map(x => x.trim()).filter(Boolean))];
  const tooLong = questions.some(q => q.length > 1000);
  const submit = () => {
    const ids = questionIds(questions.length);
    onSubmit(questionRequest(questions, ids), questions.map((question, i) => ({ id: ids[i], question })));
  };
  return <div aria-label="分析问题表单">
    <h3>{initial ? '填写需要确认的业务问题' : '添加需要确认的业务问题'}</h3>
    <p className="da-small">每行一个，每次最多 {MAX_QUESTIONS} 个。助手为每题生成 SQL，你在“检查与发布”页逐题确认；确认的问答发布后可在问数中被召回。</p>
    {suggesting && <p role="status" className="da-small">正在根据模型生成推荐问题…</p>}
    {suggested && !suggesting && <p className="da-small">已填入推荐问题，可直接提交，也可以修改、删除或新增。</p>}
    <table className="da-table" style={{ width: '100%' }}>
      <thead><tr><th style={{ width: 40 }}>序号</th><th>业务问题</th><th style={{ width: 70 }}>操作</th></tr></thead>
      <tbody>{rows.map((row, index) => <tr key={index}>
        <td>{index + 1}</td><td><textarea className="da-input" aria-label={`第 ${index + 1} 个问题`}
          value={row} maxLength={1000} rows={2} style={{ width: '100%', boxSizing: 'border-box' }}
          placeholder={index === 0 ? '例如：10月7日访问量前10的报表' : '填写问题，可留空'}
          onChange={e => setRows(previous => previous.map((value, i) => i === index ? e.target.value : value))} /></td>
        <td><button type="button" className="da-btn da-btn-sm" aria-label={`删除第 ${index + 1} 行`}
          onClick={() => setRows(previous => previous.length === 1 ? [''] : previous.filter((_, i) => i !== index))}>删除</button></td>
      </tr>)}</tbody>
    </table>
    <button type="button" className="da-btn" disabled={rows.length >= MAX_QUESTIONS} onClick={() => setRows(previous => [...previous, ''])}>＋ 增加一行</button>
    <details style={{ marginTop: 12 }}><summary>批量粘贴问题</summary>
      <textarea className="da-input" aria-label="批量粘贴问题" value={paste} onChange={e => setPaste(e.target.value)}
        rows={4} style={{ width: '100%', boxSizing: 'border-box' }} placeholder="每行一个问题" />
      <button type="button" className="da-btn" disabled={!paste.trim()}
        onClick={() => {
          const merged = [...new Set([...questions, ...paste.split(/\r?\n/).map(x => x.trim()).filter(Boolean)])];
          if (merged.length > MAX_QUESTIONS || merged.some(q => q.length > 1000)) {
            setPasteError(`加入后最多 ${MAX_QUESTIONS} 个不同问题，每题最多 1000 字符，请缩小粘贴范围。`); return;
          }
          setRows(merged); setPaste(''); setPasteError(null);
        }}>加入表格</button>
      {pasteError && <p role="alert">{pasteError}</p>}
    </details>
    <p role="status" className="da-small">{questions.length} 个不同问题 · 提交后自动进入“检查与发布”，SQL 生成后逐题确认。</p>
    {(questions.length > MAX_QUESTIONS || tooLong) && <p role="alert">每次最多 {MAX_QUESTIONS} 个问题，每个问题最多 1000 字符，请调整后提交。</p>}
    <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
      {onCancel && <button className="da-btn" onClick={onCancel}>取消</button>}
      <button className="da-btn da-btn-primary" disabled={!questions.length || questions.length > MAX_QUESTIONS || tooLong}
        onClick={submit}>提交问题</button>
    </div>
  </div>;
}
